# dart sets the source map's file offset from the node; a NIR node has none, Julia's line table taking
# that place with the source map (translateStatement)
# one compiled body for every kind of node (@nospecialize, inferred once): the @exhaustive match below
# dispatches on the kind, so a body per kind of caller's node would only repeat it
@parity "dart2wasm/lib/code_generator.dart:665 AstCodeGenerator.translateExpression" @nospecializeinfer function translate_expression(self::AstCodeGenerator, @nospecialize(node::Union{NirValue,NirStmt}), expected_type::WasmBuilder.IR.ValueType)::WasmBuilder.IR.ValueType
    try
        # dart's `node.accept1(this, expectedType)`: the visitor of the node's kind
        local result_type = node isa NirValue ? (@exhaustive node::NirValue begin
            (s::NirSSA) => visit_variable_get(self, s, expected_type)
            (a::NirArgument) => a.n == 1 ? visit_this_expression(self, a, expected_type) : visit_variable_get(self, a, expected_type)
            (c::NirConst) => let v = c.c.val
                v === nothing ? visit_null_literal(self, c, expected_type) :
                v isa String ? visit_string_literal(self, c, expected_type) :
                v isa Bool ? visit_bool_literal(self, c, expected_type) :
                v isa Int64 ? visit_int_literal(self, c, expected_type) :
                v isa Float64 ? visit_double_literal(self, c, expected_type) :
                visit_constant_expression(self, c, expected_type)
            end
            (g::NirGlobal) => dart_type_of(self, g) <: Function ? visit_static_tear_off(self, g, expected_type) : visit_static_get(self, g, expected_type)
        end) : (@exhaustive node::NirStmt begin
            # a call of a builtin that is a Kernel node of its own: a field read, a field write, a type
            # test, a throw, a tuple (dart's record); every other builtin a static invocation
            (c::NirCall) => let f = nir_callee(c),
                    # a tuple's field by its position, a NamedTuple's by its name: Kernel's record gets
                    record_get(R::Type, K::Type) = f === Core.getfield && length(c.args) >= 3 && c.args[3] isa NirConst &&
                        c.args[3].c.val isa K && (let t = dart_type_of(self, c.args[2]); t isa DataType && isconcretetype(t) && t <: R end)
                # `x === nothing` with x of a type that admits nothing and is no Nothing itself: Kernel's EqualsNull
                equals_null() = f === Core.:(===) && length(c.args) == 3 && (let ts = (dart_type_of(self, c.args[2]), dart_type_of(self, c.args[3]))
                        count(==(Nothing), ts) == 1 && all(t -> Nothing <: t, ts) end)
                record_get(Tuple, Int) ? visit_record_index_get(self, c, expected_type) :
                record_get(NamedTuple, Symbol) ? visit_record_name_get(self, c, expected_type) :
                f === Core.getfield ? visit_instance_get(self, c, expected_type) :
                f === Core.setfield! ? visit_instance_set(self, c, expected_type) :
                f === Core.setglobal! ? visit_static_set(self, c, expected_type) :
                f === Core.isa ? visit_is_expression(self, c, expected_type) :
                f === Core.typeassert ? visit_as_expression(self, c, expected_type) :
                f === Core.throw ? visit_throw(self, c, expected_type) :
                f === Core.tuple ? visit_record_literal(self, c, expected_type) :
                f === Core.Intrinsics.not_int && length(c.args) == 2 && dart_type_of(self, c.args[2]) === Bool ? visit_not(self, c, expected_type) :
                equals_null() ? visit_equals_null(self, c, expected_type) :
                visit_static_invocation(self, c, expected_type)
            end
            (i::NirInvoke) => !Base.issingletontype(dart_type_of(self, i.args[1])) ? visit_instance_invocation(self, i, expected_type) :
                # a call of Base's == with two operands: Kernel's EqualsCall
                dart_type_of(self, i.args[1]) === typeof(==) && length(i.args) == 3 ? visit_equals_call(self, i, expected_type) :
                visit_static_invocation(self, i, expected_type)
            (n::NirNew) => visit_constructor_invocation(self, n, expected_type)
            (g::NirGlobalRead) => visit_static_get(self, g, expected_type)
            (p::NirPi) => visit_as_expression(self, p, expected_type)
            NirForeignCall => reject!(Unquarantined("src/julia: a foreigncall, a quarantined host import (dev/MARCH.md 1.F)"), "$(self.enclosing_member)")
            # Julia's bounds-check flag, a Bool constant as Julia's codegen answers it (codegen.cpp,
            # bounds_check_enabled): true under --check-bounds=yes, false under =no (julia.h's
            # JL_OPTIONS_CHECK_BOUNDS_ON 1 and _OFF 2, read from the compiling process), else the
            # statement's own argument, false where the optimizer resolved an @inbounds region, true
            # with none
            (s::NirBoundscheck) => let opt = Base.JLOptions().check_bounds,
                    arg = isempty(s.args) ? true : (s.args[1] isa NirConst && s.args[1].c.val isa Bool ? s.args[1].c.val :
                        reject!(Internal("dart2wasm/lib/code_generator.dart:665 AstCodeGenerator.translateExpression: a bounds-check flag of $(s.args[1])"), "$(self.enclosing_member)"))
                WasmBuilder.i32_const(self.b[], (opt == 1 ? true : opt == 2 ? false : arg) ? 1 : 0)
                WasmBuilder.IR.NumType_i32
            end
            NirGCPreserveBegin => reject!(Unquarantined("src/julia: Julia's Expr(:gc_preserve_begin) as a value"), "$(self.enclosing_member)")
            NirGCPreserveEnd => reject!(Unquarantined("src/julia: Julia's Expr(:gc_preserve_end)"), "$(self.enclosing_member)")
            NirTheException => reject!(Internal("dart2wasm/lib/code_generator.dart:665 AstCodeGenerator.translateExpression: Julia's Expr(:the_exception), a statement visit_block translates, as a value"), "$(self.enclosing_member)")
            NirThrowUndefIfNot => reject!(Unquarantined("src/julia: Julia's Expr(:throw_undef_if_not)"), "$(self.enclosing_member)")
            NirCFunction => reject!(Unquarantined("src/julia: Julia's Expr(:cfunction), a quarantined host import (dev/MARCH.md 1.F)"), "$(self.enclosing_member)")
            NirInvokeModify => reject!(Unquarantined("src/julia: Julia's Expr(:invoke_modify)"), "$(self.enclosing_member)")
            NirPhi => reject!(Unquarantined("dev/MARCH.md 1.D: the stackifier, Julia's PhiNode as wasm's structured control"), "$(self.enclosing_member)")
            NirPhiC => reject!(Internal("dart2wasm/lib/code_generator.dart:665 AstCodeGenerator.translateExpression: Julia's PhiCNode, a statement visit_block translates, as a value"), "$(self.enclosing_member)")
            NirEnter => reject!(Unquarantined("dev/MARCH.md 1.D: Julia's EnterNode, a try region"), "$(self.enclosing_member)")
            NirLeave => reject!(Internal("dart2wasm/lib/code_generator.dart:665 AstCodeGenerator.translateExpression: Julia's Expr(:leave) as a value"), "$(self.enclosing_member)")
            NirPopException => reject!(Internal("dart2wasm/lib/code_generator.dart:665 AstCodeGenerator.translateExpression: Julia's Expr(:pop_exception) as a value"), "$(self.enclosing_member)")
            NirLoopInfo => reject!(Internal("dart2wasm/lib/code_generator.dart:665 AstCodeGenerator.translateExpression: Julia's Expr(:loopinfo) as a value"), "$(self.enclosing_member)")
            NirUpsilon => reject!(Internal("dart2wasm/lib/code_generator.dart:665 AstCodeGenerator.translateExpression: Julia's UpsilonNode as a value"), "$(self.enclosing_member)")
            NirGoto => reject!(Internal("dart2wasm/lib/code_generator.dart:665 AstCodeGenerator.translateExpression: Julia's GotoNode as a value"), "$(self.enclosing_member)")
            NirGotoIfNot => reject!(Internal("dart2wasm/lib/code_generator.dart:665 AstCodeGenerator.translateExpression: Julia's GotoIfNot as a value"), "$(self.enclosing_member)")
            NirReturn => reject!(Internal("dart2wasm/lib/code_generator.dart:665 AstCodeGenerator.translateExpression: Julia's ReturnNode as a value"), "$(self.enclosing_member)")
            NirUnreachable => reject!(Internal("dart2wasm/lib/code_generator.dart:665 AstCodeGenerator.translateExpression: Julia's unreachable ReturnNode as a value"), "$(self.enclosing_member)")
            NirNothing => reject!(Internal("dart2wasm/lib/code_generator.dart:665 AstCodeGenerator.translateExpression: an emptied statement as a value"), "$(self.enclosing_member)")
        end)
        convert_type(self.translator, self.b[], result_type, expected_type)
        return expected_type
    catch
        _print_location(self, node)
        rethrow()
    end
end

# a used statement is a variable declared with its value as the initializer, `node` its SSA value
@parity "dart2wasm/lib/code_generator.dart:690 AstCodeGenerator.translateVariableDeclaration" function translate_variable_declaration(self::AstCodeGenerator, node::NirSSA)::Nothing
    try
        visit_variable(self, node)
    catch
        _print_location(self, self.body.stmts[node.id])
        rethrow()
    end
    return nothing
end

# a variable is declared by its statement (visitVariable); a parameter is none, its local set up by
# _setupLocalParameters
@parity "dart2wasm/lib/code_generator.dart:702 AstCodeGenerator.translateVariable" function translate_variable(self::AstCodeGenerator, node::Union{NirSSA,NirArgument})::Nothing
    node isa NirSSA || reject!(Internal("dart2wasm/lib/code_generator.dart:702 AstCodeGenerator.translateVariable: $node is a parameter, whose local _setupLocalParameters sets up"), "$(self.enclosing_member)")
    try
        visit_variable(self, node)
    catch
        _print_location(self, self.body.stmts[node.id])
        rethrow()
    end
    return nothing
end

"""
Generate the code of one statement of the function's NIR body. dart's `node.accept(this)` is the
visitor's double dispatch over Kernel's statement classes; here one `@exhaustive` arm per NIR form,
no wildcard. `variable` is the statement's SSA value when a later statement reads it (`used`), the
one fact Julia's flat IR keeps apart from the statement (Kernel nests a used expression in its
parent), and `nothing` otherwise: a used value is Kernel's `VariableDeclaration` with its
initializer, a local (translateVariableDeclaration), an unused one an `ExpressionStatement`
(visitExpressionStatement, the void marker expected); a return is a `ReturnStatement`, an emptied
statement an `EmptyStatement`. A try region's entry, exit and exception-stack pop are the
stackifier's structure (visit_block) and emit nothing here. The other Julia-only forms (the flat IR's
jumps and merges, exception-edge values, GC preservation, loop hints) reject, located, until the
stackifier (dev/MARCH.md 1.D), and a foreign call or C function pointer until the host imports (1.F).
dart's source-map offset is set from the node; the NIR's line table takes that place with the source
map.
"""
@parity "dart2wasm/lib/code_generator.dart:714 AstCodeGenerator.translateStatement" @nospecializeinfer function translate_statement(self::AstCodeGenerator, @nospecialize(node::NirStmt), variable::Union{NirSSA,Nothing})::Nothing
    local at = "dart2wasm/lib/code_generator.dart:714 AstCodeGenerator.translateStatement"
    @exhaustive node::NirStmt begin
        (s::NirCall) => variable === nothing ? visit_expression_statement(self, s) : translate_variable_declaration(self, variable)
        (s::NirInvoke) => variable === nothing ? visit_expression_statement(self, s) : translate_variable_declaration(self, variable)
        (s::NirNew) => variable === nothing ? visit_expression_statement(self, s) : translate_variable_declaration(self, variable)
        (s::NirGlobalRead) => variable === nothing ? visit_expression_statement(self, s) : translate_variable_declaration(self, variable)
        (s::NirReturn) => visit_return_statement(self, s)
        (s::NirNothing) => visit_empty_statement(self, s)
        (s::NirForeignCall) => reject!(Unquarantined("dev/MARCH.md 1.F: a foreign call, a host import"), at)
        (s::NirCFunction) => reject!(Unquarantined("dev/MARCH.md 1.F: a C function pointer, a host import"), at)
        (s::NirBoundscheck) => variable === nothing ? visit_expression_statement(self, s) : translate_variable_declaration(self, variable)
        (s::NirGCPreserveBegin) => reject!(Unquarantined("dev/MARCH.md 1.D: Julia's GC preservation region"), at)
        (s::NirGCPreserveEnd) => reject!(Unquarantined("dev/MARCH.md 1.D: Julia's GC preservation region"), at)
        # control leaves a try region by the stackifier's branch out of its TRY_TABLE (visit_block)
        (s::NirLeave) => nothing
        # Julia's exception stack has no reader: the_exception reads its catch's CATCH local
        # (visit_block), where it is not in its catch's first block it rejects, and
        # Base.current_exceptions is a foreign call
        (s::NirPopException) => nothing
        (s::NirTheException) => reject!(Internal("$at: the caught exception, which visit_block reads from its catch's CATCH local, as a statement"), at)
        (s::NirLoopInfo) => reject!(Unquarantined("dev/MARCH.md 1.D: Julia's loop hints"), at)
        (s::NirThrowUndefIfNot) => reject!(Unquarantined("dev/MARCH.md 1.D: Julia's undefined-variable check"), at)
        (s::NirInvokeModify) => reject!(Unquarantined("dev/MARCH.md 1.D: an atomic field modify"), at)
        (s::NirGoto) => reject!(Internal("$at: a jump of the flat IR, which the stackifier's BR carries (visit_block), as a statement"), at)
        (s::NirGotoIfNot) => reject!(Internal("$at: a conditional jump of the flat IR, which the stackifier's BR_IF or BR_UNLESS carries (visit_block), as a statement"), at)
        # Julia's codegen emits a trap where Julia proved the code unreachable
        (s::NirUnreachable) => WasmBuilder.unreachable(self.b[])
        (s::NirPhi) => reject!(Internal("$at: an SSA merge, which visit_block reads from its incoming register, as a statement"), at)
        (s::NirPi) => variable === nothing ? visit_expression_statement(self, s) : translate_variable_declaration(self, variable)
        # the try region's TRY_TABLE, which the stackifier placed, opens it (visit_block)
        (s::NirEnter) => nothing
        (s::NirUpsilon) => reject!(Internal("$at: an exception-edge value, which visit_block writes to its PhiCs' registers, as a statement"), at)
        (s::NirPhiC) => reject!(Internal("$at: an exception-edge merge, which visit_block reads from its register, as a statement"), at)
    end
    return nothing
end

